// Shared by the host and the public-page diagnostic. Credentials are arguments
// to Fill and are never stored in these scripts or diagnostic output.
internal static class LoginFormScripts {
 internal const string Resolver="const u=document.querySelector('#login-username'),p=document.querySelector('#login-password'),legacy=document.querySelector('#login-button');const formButtons=p?.form?Array.from(p.form.querySelectorAll('button[type=submit]')):[];const named=Array.from(document.querySelectorAll('button')).filter(e=>e.type==='submit'&&/^(sign in|log in|เข้าสู่ระบบ|ลงชื่อเข้าใช้)$/i.test((e.textContent||'').trim()));const b=legacy||(formButtons.length===1?formButtons[0]:named.length===1?named[0]:null);";
 internal const string ReadyBody="return !!(u&&p&&b&&!u.disabled&&!p.disabled&&!u.readOnly&&!p.readOnly);";
 internal const string FillBody="if(!u||!p||!b||u.disabled||p.disabled||u.readOnly||p.readOnly)return false;const set=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;set.call(u,username);u.dispatchEvent(new Event('input',{bubbles:true}));u.dispatchEvent(new Event('change',{bubbles:true}));set.call(p,password);p.dispatchEvent(new Event('input',{bubbles:true}));p.dispatchEvent(new Event('change',{bubbles:true}));return true;";
 internal const string SubmitBody="if(!u||!p||!b)return 'MISSING';const modal=Array.from(document.querySelectorAll('[role=dialog],[aria-modal=true]')).some(e=>e.getBoundingClientRect().width>0&&e.getBoundingClientRect().height>0);if(modal)return 'CHALLENGE';if(b.disabled||b.getAttribute('aria-disabled')==='true')return 'PENDING';b.click();return 'CLICKED';";
 internal static string Ready {get{return "(()=>{"+Resolver+ReadyBody+"})()";}}
 internal static string Fill(string usernameJson,string passwordJson){return "((username,password)=>{"+Resolver+FillBody+"})("+usernameJson+","+passwordJson+")";}
 internal static string Submit {get{return "(()=>{"+Resolver+SubmitBody+"})()";}}
 // Broader than the original detector: the live page reports a rejected login as
 // plain body text ("Incorrect username or password."), not as an alert, and it
 // also shows mail-code, passkey and rate-limit screens after the password step.
 internal const string IssueBody="const t=(document.body?(document.body.innerText||''):'').toLowerCase();const visible=s=>Array.from(document.querySelectorAll(s)).some(e=>e.getBoundingClientRect().width>0&&e.getBoundingClientRect().height>0);if(visible('iframe[src*=captcha],iframe[src*=arkoselabs],[data-testid*=captcha]')||/verify you are human|security challenge|ยืนยันว่าคุณเป็นมนุษย์/.test(t))return 'CUSTOMER_CAPTCHA_REQUIRED';if(visible('input[autocomplete=one-time-code]')||/verification code|two.step verification|2.step verification|enter the code|check your email|รหัสยืนยัน|กรอกรหัส|ตรวจอีเมล/.test(t))return 'CUSTOMER_OTP_REQUIRED';if(/verify (using|with|on) (your )?(phone|mobile)|check your (phone|mobile)|approve (the )?(login|request)|โปรดเปิดแอป roblox|โทรศัพท์มือถือหรือแท็บเล็ตที่ลงชื่อเข้าใช้อยู่/.test(t))return 'CUSTOMER_PHONE_VERIFICATION';if(/verify (it.s|your identity|your account)|confirm your identity|sign in with a passkey|use your passkey|ยืนยันตัวตน|ตรวจสอบตัวตน|พาสคีย์/.test(t))return 'CUSTOMER_IDENTITY_VERIFICATION';if(/too many (attempts|requests|tries)|พยายามหลายครั้งเกินไป|บ่อยเกินไป/.test(t))return 'CUSTOMER_LOGIN_RATE_LIMITED';if(/incorrect (username|password)|username or password you entered is incorrect|invalid (username|password)|wrong password|ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง|รหัสผ่านไม่ถูกต้อง|รหัสผ่านผิด/.test(t))return 'CUSTOMER_PASSWORD_INVALID';return '';";
 internal static string Issue {get{return "(()=>{"+IssueBody+"})()";}}
 internal const string ViewBody="const raw=(document.body?(document.body.innerText||''):'').split(String.fromCharCode(13)).join(' ').split(String.fromCharCode(10)).join(' ');const redacted=username?raw.split(username).join('***'):raw;return JSON.stringify({path:location.pathname,text:redacted.slice(0,300)});";
 internal static string View(string usernameJson){return "((username)=>{"+ViewBody+"})("+usernameJson+")";}
}
